import json,sys
d=json.load(open('sheets.json'))
def walk(n,out):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c,out)
        elif t=='listItem':
            out.append('\n- ')
            for c in n.get('content',[]): walk(c,out)
        else:
            for k in ('content','inlineContent','items','sections','primaryContentSections'):
                if k in n:
                    for c in n[k]: walk(c,out)
    elif isinstance(n,list):
        for c in n: walk(c,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
print(''.join(out))
print('---ALERT---', d['metadata'].get('customMetadata'))
